import React, { useState } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";
import Preview from "./components/Preview";
import Questionnaire from "./components/Questionnaire";

function App() {
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    incomeRange: "",
    spendingRange: "",
    savingRange: "",
    categories: [],
    priorities: [],
    limits: {}
  });

  return (
    <>
      {step === "login" && (
        <Login onLogin={() => setStep("income")} />
      )}

      {step === "income" && (
        <IncomeCategory
          onNext={(val) => {
            setData({ ...data, income: val });
            setStep("questionnaire");
          }}
        />
      )}

      {step === "questionnaire" && (
        <Questionnaire
          data={data}
          setData={setData}
          onNext={() => setStep("priority")}
          onBack={() => setStep("income")}
        />
      )}

      {step === "priority" && (
        <SpendingPriority
          data={data}
          setData={setData}
          onNext={() => setStep("budget")}
          onBack={() => setStep("questionnaire")}
        />
      )}

      {step === "budget" && (
        <BudgetLimits
          data={data}
          setData={setData}
          selectedCategories={data.priorities}
          onNext={() => setStep("preview")}
          onBack={() => setStep("priority")}
        />
      )}

      {step === "priority" && (
  <SpendingPriority
    selected={data.categories}
    onNext={(categories) => {
      setData({ ...data, categories });  // ✅ FIX
      setStep("budget");
    }}
  />
)}

      {step === "dashboard" && <Dashboard />}
    </>
  );
}

export default App;
